"""Message signing and verification for Ethereum and Bitcoin.

Two widely deployed standards are implemented on top of the internal ECDSA
engine:

* Ethereum ``personal_sign`` / EIP-191 (``0x19`` prefix with the
  ``"Ethereum Signed Message:\\n"`` tag), producing a 65-byte ``r || s || v``
  signature where ``v`` is ``recovery_id + 27``.
* Bitcoin signed messages (the ``"\\x18Bitcoin Signed Message:\\n"`` magic),
  producing the classic Base64 ``header || r || s`` signature used by wallets
  such as Bitcoin Core's ``signmessage``.

Only the Python standard library and internal libcrypto primitives are used.
"""
from __future__ import annotations

import base64
from typing import Union

from .addresses import AddressGenerator
from .hash import double_sha256, keccak256
from .signing import Signature, recover_public_key, sign

_ETHEREUM_PREFIX = b"\x19Ethereum Signed Message:\n"
_BITCOIN_MAGIC = b"\x18Bitcoin Signed Message:\n"


def _to_bytes(message: Union[str, bytes]) -> bytes:
    if isinstance(message, str):
        return message.encode("utf-8")
    if isinstance(message, (bytes, bytearray)):
        return bytes(message)
    raise TypeError("message must be str or bytes.")


def _encode_varint(value: int) -> bytes:
    """Encode a Bitcoin CompactSize (varint) unsigned integer."""
    if value < 0:
        raise ValueError("varint value must be non-negative.")
    if value < 0xFD:
        return bytes([value])
    if value <= 0xFFFF:
        return b"\xfd" + value.to_bytes(2, "little")
    if value <= 0xFFFFFFFF:
        return b"\xfe" + value.to_bytes(4, "little")
    return b"\xff" + value.to_bytes(8, "little")


# ---------------------------------------------------------------------------
# Ethereum (EIP-191 personal_sign)
# ---------------------------------------------------------------------------

def hash_ethereum_message(message: Union[str, bytes]) -> bytes:
    """Return the EIP-191 keccak256 digest for an Ethereum personal message."""
    payload = _to_bytes(message)
    prefixed = _ETHEREUM_PREFIX + str(len(payload)).encode("ascii") + payload
    return keccak256(prefixed)


def sign_message_ethereum(private_key: int, message: Union[str, bytes]) -> bytes:
    """Sign a message with Ethereum's ``personal_sign`` scheme.

    Returns a 65-byte signature laid out as ``r (32) || s (32) || v (1)`` where
    ``v`` is ``recovery_id + 27``.
    """
    digest = hash_ethereum_message(message)
    signature = sign(private_key, digest)
    if signature.recovery_id is None:
        raise ValueError("Signature is missing a recovery id.")
    v = 27 + signature.recovery_id
    return signature.to_compact() + bytes([v])


def recover_address_ethereum(message: Union[str, bytes], signature: bytes) -> str:
    """Recover the EIP-55 checksummed address that signed an Ethereum message."""
    if len(signature) != 65:
        raise ValueError("Ethereum signature must be 65 bytes.")
    v = signature[64]
    if v >= 27:
        v -= 27
    # Some tooling encodes v as the EIP-155 chain value; reduce to 0/1 parity.
    recovery_id = v & 0x01 if v > 3 else v
    digest = hash_ethereum_message(message)
    sig = Signature.from_compact(signature[:64])
    public_key = recover_public_key(digest, sig, recovery_id, compressed=False)
    return AddressGenerator.from_public_key(public_key, "default", "ethereum")


def verify_message_ethereum(
    address: str, message: Union[str, bytes], signature: bytes
) -> bool:
    """Verify an Ethereum personal_sign signature against an address."""
    try:
        recovered = recover_address_ethereum(message, signature)
    except Exception:  # noqa - any failure means the signature is invalid.
        return False
    return recovered.lower() == address.lower()


# ---------------------------------------------------------------------------
# Bitcoin signed messages
# ---------------------------------------------------------------------------

def hash_bitcoin_message(message: Union[str, bytes]) -> bytes:
    """Return the double-SHA256 digest for a Bitcoin signed message."""
    payload = _to_bytes(message)
    data = _BITCOIN_MAGIC + _encode_varint(len(payload)) + payload
    return double_sha256(data)


def sign_message_bitcoin(
    private_key: int,
    message: Union[str, bytes],
    *,
    compressed: bool = True,
) -> str:
    """Sign a message with Bitcoin's signed-message scheme.

    Returns the Base64-encoded ``header || r || s`` signature, where ``header``
    is ``27 + recovery_id (+4 if the address uses a compressed public key)``.
    """
    digest = hash_bitcoin_message(message)
    signature = sign(private_key, digest)
    if signature.recovery_id is None:
        raise ValueError("Signature is missing a recovery id.")
    header = 27 + signature.recovery_id + (4 if compressed else 0)
    raw = bytes([header]) + signature.to_compact()
    return base64.b64encode(raw).decode("ascii")


def recover_address_bitcoin(
    message: Union[str, bytes],
    signature: str,
    *,
    network: str = "bitcoin",
) -> str:
    """Recover the P2PKH address that signed a Bitcoin message."""
    try:
        raw = base64.b64decode(signature, validate=True)
    except Exception as exc:  # noqa: BLE001 - malformed base64 is a value error.
        raise ValueError(f"Invalid Base64 signature: {exc}") from exc
    if len(raw) != 65:
        raise ValueError("Bitcoin signature must be 65 bytes after Base64 decoding.")

    header = raw[0]
    if not 27 <= header <= 34:
        raise ValueError("Invalid Bitcoin signature header byte.")
    compressed = header >= 31
    recovery_id = (header - 27) & 0x03

    digest = hash_bitcoin_message(message)
    sig = Signature.from_compact(raw[1:])
    public_key = recover_public_key(digest, sig, recovery_id, compressed=compressed)
    return AddressGenerator.from_public_key(public_key, "p2pkh", network)


def verify_message_bitcoin(
    address: str,
    message: Union[str, bytes],
    signature: str,
    *,
    network: str = "bitcoin",
) -> bool:
    """Verify a Bitcoin signed message against a P2PKH address."""
    try:
        recovered = recover_address_bitcoin(message, signature, network=network)
    except Exception:  # noqa - any failure means the signature is invalid.
        return False
    return recovered == address


__all__ = [
    "hash_ethereum_message",
    "sign_message_ethereum",
    "recover_address_ethereum",
    "verify_message_ethereum",
    "hash_bitcoin_message",
    "sign_message_bitcoin",
    "recover_address_bitcoin",
    "verify_message_bitcoin",
]
